// ============================================================
// STEP 1: Language detection — regex, FREE
// ============================================================
const inbound = $('Parse inbound teleg').item.json;
const owner = $('load owner + conversation').item.json;
const text = inbound.message_text || '';
const textLower = text.toLowerCase().trim();

const hasArabic = /[\u0600-\u06FF]/.test(text);
const detectedLang = hasArabic ? 'ar' : 'en';
const langChanged = detectedLang !== (owner.language || 'en');

// ============================================================
// STEP 2: Regex intent classification — FREE, <1ms
// Returns: interested | closing | refused | objection | unknown
// ============================================================

const PATTERNS = {
  refused: [
    /\bno\b/i, /not interested/i, /stop/i, /remove me/i, /don't contact/i,
    /already sold/i, /not selling/i, /leave me/i, /unsubscribe/i,
    /لا\b/, /مش راضي/, /بعت/, /لا تتصل/, /مو مهتم/
  ],
  closing: [
    /title deed/i, /passport/i, /\beid\b/i, /send.*form/i, /form a/i,
    /\bmou\b/i, /ready to sign/i, /send.*doc/i, /viewing/i, /photos ready/i
  ],
  interested: [
    /\byes\b/i, /\byep\b/i, /\byeah\b/i, /\bsure\b/i, /\bok\b/i, /\bokay\b/i,
    /interested/i, /tell me more/i, /go ahead/i, /sounds good/i,
    /let'?s/i, /definitely/i, /how much/i, /what price/i, /can you/i,
    /\bنعم\b/, /\bموافق\b/, /\bطبعا\b/, /\bاوك\b/, /\bتمام\b/, /\bممتاز\b/,
    /tamam/i, /maafi mushkila/i, /zain/i, /wayed/i
  ],
  objection: [
    /already listed/i, /too many agents/i, /busy/i, /wait/i, /later/i,
    /next year/i, /thinking/i, /commission/i, /\bfee\b/i, /who pays/i,
    /tenant/i, /rented/i, /occupied/i, /trust/i, /prove/i, /why should/i,
    /مؤجر/, /مش محتاج/, /في وقت لاحق/, /مكلف/, /عمولة/, /كيف أعرف/
  ]
};

// --- NEW: negation guard, runs BEFORE the pattern loop ---
const negationBefore = /\b(not|n't|no|never)\s+(sure|interested|ok|okay)\b/i;

let intent = 'unknown';
if (negationBefore.test(textLower)) {
  intent = 'objection'; // negated "sure/interested/ok" → treat as uncertain, not confirmed interest
} else {
  for (const [label, patterns] of Object.entries(PATTERNS)) {
    if (patterns.some(p => p.test(textLower) || p.test(text))) {
      intent = label;
      break; // first match wins — order matters (refused > closing > interested > objection)
    }
  }
}

// Build conversation history text for agent context
const history = $('load 10 messages').all().map(i => i.json);
const historyText = history.length > 0
  ? history.reverse().map(m => `[${m.sender.toUpperCase()}]: ${m.content}`).join('\n')
  : 'This is the first reply from this owner.';

return [{
  json: {
    owner_id: owner.id,
    conversation_id: owner.conversation_id,
    from_number: inbound.from_number,
    message_text: text,
    owner,
    history_text: historyText,
    intent,
    needs_gpt: intent === 'unknown',
    detected_lang: detectedLang,
    lang_changed: langChanged,
    agent_prompt: `OWNER CONTEXT:\nName: ${owner.owner_name}\nProperty: ${owner.property_ref || owner.area}\nArea: ${owner.area}\nBeds: ${owner.beds || 'N/A'}\nTransaction: ${owner.transaction_type}\nLanguage: ${detectedLang}\nStatus: ${owner.status}\nConversation state: ${owner.conversation_state || 'outreach'}\nOwner ID: ${owner.id}\nConversation ID: ${owner.conversation_id}\n\nCONVERSATION HISTORY (oldest to newest):\n${historyText}\n\nOWNER JUST REPLIED:\n"${text}"\n\nYOUR TASK:\n1. Understand the owner's message and intent\n2. If it is an objection, use the search_objections tool to find the best matching script\n3. Craft a personalised reply\n4. Send via send_whatsapp tool\n5. Update conversation state via update_state tool\n6. Log both messages via log_message tool\n\nThink step by step.`
  }
}];

const base = $('Code — regex intent + language detect').item.json;
const gptRaw = $json.choices?.[0]?.message?.content?.trim().toLowerCase() || 'unknown';
const validLabels = ['refused', 'closing', 'agent'];
const finalIntent = validLabels.includes(gptRaw) ? gptRaw : 'agent';

return [{
  json: {
    ...base,
    intent: finalIntent,
    intent_source: 'groq'
  }
}];

const owner = $json.owner;
const firstName = (owner.owner_name || 'there').split(' ')[0];
const lang = $json.detected_lang;

const msg = lang === 'ar'
  ? `تمام ${firstName}، لا مشكلة على الإطلاق. لو تغير رأيك في أي وقت، أنا هنا. يوم سعيد!`
  : `Completely understood ${firstName} — no pressure at all. If anything changes down the line, I'm always here. Have a great day!`;

return [{ json: { ...($json), reply_text: msg, new_status: 'lost', new_state: 'lost', telegram_id:$('Code — regex intent + language detect').first().json.owner.telegram_id,
    conversation_id: $('Code — regex intent + language detect').first().json.owner.conversation_id,
    source:           'template' } }];

const owner = $json.owner;
const firstName = (owner.owner_name || 'there').split(' ')[0];
const lang = $json.detected_lang;

const msg = lang === 'ar'
  ? `${firstName}، ممتاز! بمجرد ما تكون المستندات جاهزة، ابعثها وأنا أتابع معك فوراً.`
  : `Perfect ${firstName} — once you have the documents ready just send them over and I'll take it from there straight away.`;

return [{
  json: {
    reply:            msg,
    reply_text:       msg,
    new_state:        'doc_collection',
    new_status:       'active',
    telegram_id: $('Code — regex intent + language detect').first().json.owner.telegram_id,
    conversation_id: $('Code — regex intent + language detect').first().json.owner.conversation_id,
    source:      'template'
  }
}];

const items = $input.all();
const item = items[0];
const msg = item.json.message;

if (!msg?.text) return [];

return [{
  json: {
    tele_chat_id: String(msg.chat.id),  
    message_text: msg.text,
    wa_message_id: String(msg.message_id),
    timestamp: String(msg.date)
  }
}];

