const raw = $input.first().json.output;

let parsed;
try {
  // Agent sometimes wraps JSON in explanation text — extract just the JSON block
  const jsonMatch = typeof raw === 'string' 
    ? raw.match(/\{[\s\S]*\}/) 
    : null;

  const jsonString = jsonMatch ? jsonMatch[0] : raw;
  parsed = typeof jsonString === 'string' ? JSON.parse(jsonString) : jsonString;
} catch (e) {
  parsed = {};
}

return [{
  json: {
    reply_text:            parsed.reply_text            || '',
    new_state:        parsed.new_state        || 'waiting_reply',
    intent:  parsed.intent || 'unknown',
    conversation_id:  parsed.conversation_id  || $('Code — regex intent + language detect').first().json.conversation_id,
    telegram_id:     $('Code — regex intent + language detect').first().json.owner.telegram_id
  }
}];

const input = $input.first().json;

const reply           = input.reply        || input.message   || input.reply_text || '';
const telegram_id    = input.telegram_id || input.chat_id   || '';
const new_state       = input.new_state    || input.state     || 'waiting_reply';
const conversation_id = input.conversation_id                 || '';
const intent_detected = input.intent_detected || input.intent || 'unknown';
const source          = input.source       || 'agent';

return [{
  json: {
    reply,
    telegram_id,
    new_state,
    conversation_id,
    intent_detected,
    source,
    // Debug flags — remove once stable
    warn_empty_reply:   !reply           ? true : false,
    warn_missing_chat:  !telegram_id   ? true : false
  }
}];
